pe="hidden" name="id" value="<?php echo $id;?>"><label>Pending Salary</label><input class="form-control" type="number" step=".01" name="pending_salary" value="<?php echo $x['pending_salary'];?>"><br><label>Retention Release</label><input class="form-control" type="number" step=".01" name="retention_release" value="<?php echo $x['retention_release'];?>"><br><label>Deductions</label><input class="form-control" type="number" step=".01" name="deductions" value="<?php echo $x['deductions'];?>"><br><button class="btn btn-primary btn-block">Complete Settlement</button></form></div></div></aside></div></div><?php include 'footer.php';?>
